using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class PreviewSeabird
{
 public static string Run(){var prefab=Resources.Load<GameObject>("Models/Story/Seabird");if(!prefab)throw new Exception("Missing seabird");string folder="Verification/latest-plan-20261018/seabird";Directory.CreateDirectory(folder);
 for(int n=0;n<3;n++){var p=new PreviewRenderUtility();var o=UnityEngine.Object.Instantiate(prefab);try{p.AddSingleGO(o);var a=o.GetComponent<Animator>();var clip=a.runtimeAnimatorController.animationClips.First();clip.SampleAnimation(o,n*.28f);var rs=o.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);p.lights[0].intensity=1.5f;p.lights[0].transform.rotation=Quaternion.Euler(45,30,0);p.lights[1].intensity=.8f;p.lights[1].transform.rotation=Quaternion.Euler(340,210,0);p.ambientColor=new Color(.4f,.5f,.55f);var c=p.camera;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.15f,.33f,.38f);c.orthographic=true;c.orthographicSize=.85f;Vector3 d=n==0?new Vector3(1,1.2f,1.4f):n==1?new Vector3(0,3,0.1f):new Vector3(1,.12f,0);c.transform.position=b.center+d.normalized*4;c.transform.LookAt(b.center);c.nearClipPlane=.01f;c.farClipPlane=10;p.BeginPreview(new Rect(0,0,900,700),GUIStyle.none);p.Render(true);var rt=(RenderTexture)p.EndPreview();var prev=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();RenderTexture.active=prev;File.WriteAllBytes(folder+"/view-"+n+".png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{p.Cleanup();}}
 return "Rendered three source-model poses";}
}
